import numpy as np
from PIL import Image
im=np.array(Image.open('/app/output/clear_main_canvas_cam.png'))
M=(im.mean(2)<80)
def target_to_canvas(u,v):
 x=.0135925-(v+.5)*.00022186;y=.1135925-(u+.5)*.00022186
 return np.array([512- y*2344.588/.60,512+(-x-.1)*2344.588/.60])
for u,v in [(380,356),(420,342),(460,324),(500,306),(550,292),(537,440),(534,484),(550,567),(600,659)]:
 c=target_to_canvas(u,v)
 # target-coordinate tangent approx first roof slope u+,v-; for other points use vertical-ish etc
 if v>400 and v<500:t=np.array([.2,1.])
 elif u>540 and v>490 and u<620:t=np.array([.4,.9])
 elif u>520 and v>400:t=np.array([0,1.])
 else:t=np.array([1.,-.35])
 # transform tangent by target pixel mapping screen scale
 # tangent in canvas follows du=+0.87*target du, dv=.87*target dv
 tc=t.copy();tc[1]*=1;tc=tc/np.linalg.norm(tc);n=np.array([-tc[1],tc[0]])
 vals=[]
 for d in np.arange(-40,41,1):
  p=np.rint(c+n*d).astype(int);x,y=p
  if 0<=x<1024 and 0<=y<1024 and M[y,x]:vals.append(d)
 if vals:print((u,v),'->',np.round(c,1),'width',max(vals)-min(vals)+1,'offset',min(vals),max(vals))
